/**
 * Example website templates shown in the FUSE gallery: three per category, made by FUSE in Indonesian.
 * Pages are generated by scripts/templates-local/generate.mjs and photographed by capture.py into
 * public/templates-local/<category>/<slug>/<page>.webp (+ @thumb, and home@m for the first page on mobile).
 */
import type { CategoryId } from "./site-categories";

export type TemplatePage = { id: string; src: string; thumb: string };
export type SiteTemplate = {
  slug: string;
  name: string;
  source: string | null;
  license: string;
  licenseUrl: string | null;
  attribution: string | null;
  /** First template of a category: its colours match the hero mood. */
  mood: boolean;
  mobile: string;
  pages: readonly TemplatePage[];
};

/** Page ids per category, the first one being the template's main page. */
export const TEMPLATE_PAGE_IDS: Record<CategoryId, readonly string[]> = {
  marketplace: ["home", "catalog", "product", "cart", "checkout", "seller", "login"],
  ecommerce: ["home", "catalog", "product", "cart", "checkout", "account", "login"],
  lms: ["home", "courses", "course", "lesson", "instructors", "login"],
  saas: ["overview", "analytics", "billing", "team", "settings", "login"],
  clinic: ["home", "doctors", "doctor_detail", "booking", "confirmation", "departments", "login"],
  company: ["home", "services", "portfolio", "portfolio_detail", "about", "team", "contact"],
  news: ["home", "article", "category", "author", "search"],
  api: ["intro", "quickstart", "endpoint", "schema", "code", "auth"],
};

function example(category: CategoryId, slug: string, name: string, mood: boolean): SiteTemplate {
  const dir = `/templates-local/${category}/${slug}`;
  return {
    slug,
    name,
    source: null,
    license: "Contoh FUSE",
    licenseUrl: null,
    attribution: null,
    mood,
    mobile: `${dir}/home@m.webp`,
    pages: TEMPLATE_PAGE_IDS[category].map((id) => ({ id, src: `${dir}/${id}.webp`, thumb: `${dir}/${id}@thumb.webp` })),
  };
}

/** Per category: [mood colours, "terang bersih", "gelap editorial"]. */
const NAMES: Record<CategoryId, readonly [[string, string], [string, string], [string, string]]> = {
  marketplace: [["pasar-padang", "Pasar Padang"], ["lapak-terang", "Lapak Terang"], ["bursa-malam", "Bursa Malam"]],
  ecommerce: [["toko-bahari", "Toko Bahari"], ["butik-putih", "Butik Putih"], ["galeri-arang", "Galeri Arang"]],
  lms: [["akademi-curug", "Akademi Curug"], ["kelas-terang", "Kelas Terang"], ["pustaka-malam", "Pustaka Malam"]],
  saas: [["dasbor-senja", "Dasbor Senja"], ["panel-jernih", "Panel Jernih"], ["konsol-malam", "Konsol Malam"]],
  clinic: [["klinik-samudra", "Klinik Samudra"], ["klinik-sehati", "Klinik Sehati"], ["klinik-nirmala", "Klinik Nirmala"]],
  company: [["studio-savana", "Studio Savana"], ["karya-lapang", "Karya Lapang"], ["biro-arang", "Biro Arang"]],
  news: [["kabar-fajar", "Kabar Fajar"], ["warta-terang", "Warta Terang"], ["harian-senyap", "Harian Senyap"]],
  api: [["dok-salju", "Dok Salju"], ["referensi-jernih", "Referensi Jernih"], ["terminal-malam", "Terminal Malam"]],
};

const of = (c: CategoryId) => {
  const [a, b, d] = NAMES[c];
  return [example(c, a[0], a[1], true), example(c, b[0], b[1], false), example(c, d[0], d[1], false)] as const;
};

export const SITE_TEMPLATES: Record<CategoryId, readonly [SiteTemplate, SiteTemplate, SiteTemplate]> = {
  marketplace: of("marketplace"),
  ecommerce: of("ecommerce"),
  lms: of("lms"),
  saas: of("saas"),
  clinic: of("clinic"),
  company: of("company"),
  news: of("news"),
  api: of("api"),
};

export function templatesFor(id: CategoryId): readonly SiteTemplate[] {
  return SITE_TEMPLATES[id];
}
